/**
 * zlibInflate against Node's zlib as the oracle (Codex XREVIEW HOLD 6293967301 on
 * orchestkit#4801): an incomplete literal/length tree was accepted.
 */

import { deflateSync, inflateSync } from "node:zlib";
import { describe, expect, test } from "vitest";
import { zlibInflate } from "../src/inflate.js";

function oracle(bytes: Uint8Array, limit: number): Uint8Array | null {
  try {
    const out = inflateSync(Buffer.from(bytes));
    return out.length <= limit ? Uint8Array.from(out) : null;
  } catch {
    return null;
  }
}

describe("zlibInflate agrees with Node's zlib", () => {
  test("Codex's incomplete literal/length tree is refused, as zlib refuses it", () => {
    const bytes = Uint8Array.from(Buffer.from("789c05c0010900000080a0feaf4e1000020001", "hex"));
    expect(oracle(bytes, 3)).toBeNull();
    expect(zlibInflate(bytes, 3)).toBeNull();
  });

  test("round trips of real deflate output at every level and strategy", () => {
    let seed = 7;
    const rnd = (): number => ((seed = (seed * 1103515245 + 12345) >>> 0) >>> 16) & 0xff;
    const inputs: Buffer[] = [
      Buffer.alloc(0),
      Buffer.from([0]),
      Buffer.from("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"),
      Buffer.from(Array.from({ length: 5000 }, () => rnd())),
      Buffer.from(Array.from({ length: 70000 }, (_, i) => (i % 97 < 5 ? rnd() : i % 7))),
    ];
    for (const input of inputs) {
      for (const level of [0, 1, 6, 9]) {
        for (const strategy of [0, 1, 2, 3, 4]) {
          const z = Uint8Array.from(deflateSync(input, { level, strategy }));
          const got = zlibInflate(z, input.length);
          expect(got === null ? null : Buffer.from(got).equals(input)).toBe(true);
        }
      }
    }
  });

  test("seeded mutation fuzz: every mutated stream gives the same answer as zlib", () => {
    let seed = 20261020;
    const rnd = (n: number): number => (((seed = (seed * 1664525 + 1013904223) >>> 0) >>> 8) % n);
    const base = [
      Uint8Array.from(deflateSync(Buffer.from("the quick brown fox jumps over the lazy dog ".repeat(40)))),
      Uint8Array.from(deflateSync(Buffer.from(Array.from({ length: 300 }, (_, i) => (i * 31) & 0xff)), { level: 9 })),
      Uint8Array.from(deflateSync(Buffer.from([0, 220, 30, 30]))),
    ];
    let disagreements: string[] = [];
    for (let k = 0; k < 3000; k++) {
      const src = base[k % base.length];
      const m = Uint8Array.from(src);
      const flips = 1 + rnd(3);
      for (let f = 0; f < flips; f++) m[rnd(m.length)] ^= 1 << rnd(8);
      const limit = 4096;
      const want = oracle(m, limit);
      const got = zlibInflate(m, limit);
      const same = want === null ? got === null : got !== null && Buffer.from(got).equals(Buffer.from(want));
      if (!same) disagreements.push(Buffer.from(m).toString("hex"));
    }
    expect(disagreements.slice(0, 3)).toEqual([]);
  });
});
